"use client";

import "../../styles/teum-base.css";
import "../../styles/components/breadcrumbs.css";
import { CaretRight, DotsThree } from "@phosphor-icons/react";
import type { ComponentPropsWithRef, ReactNode } from "react";
import { cn } from "../../lib/cn";

export type BreadcrumbItem = { label: string; href?: string; icon?: ReactNode };
export type BreadcrumbsProps = ComponentPropsWithRef<"nav"> & { items: readonly BreadcrumbItem[]; maxItems?: number; label?: string };

export function Breadcrumbs({ items, maxItems = 4, label = "Breadcrumb", className, ...props }: BreadcrumbsProps) {
  const collapsed = items.length > maxItems;
  const visibleItems = collapsed ? [items[0], { label: "More" }, ...items.slice(-(maxItems - 2))] : items;
  return (
    <nav className={cn("teum-breadcrumbs", className)} aria-label={label} {...props}>
      <ol>
        {visibleItems.map((item, index) => {
          const current = index === visibleItems.length - 1;
          const collapsedItem = collapsed && index === 1;
          return (
            <li key={`${item.label}-${index}`}>
              {index > 0 && <CaretRight className="teum-breadcrumbs__separator" aria-hidden="true" />}
              {collapsedItem ? <span className="teum-breadcrumbs__ellipsis" role="img" aria-label="Collapsed breadcrumbs"><DotsThree weight="bold" /></span> : item.href && !current ? <a href={item.href}>{item.icon}{item.label}</a> : <span aria-current={current ? "page" : undefined}>{item.icon}{item.label}</span>}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-breadcrumbs ol { display: flex; min-width: 0; align-items: center; gap: 3px; margin: 0; padding: 0; list-style: none; }

.teum-breadcrumbs li { display: flex; min-width: 0; align-items: center; gap: 3px; }

.teum-breadcrumbs a,
.teum-breadcrumbs li > span:not(.teum-breadcrumbs__separator) { display: inline-flex; min-width: 0; align-items: center; gap: 5px; border-radius: 4px; color: var(--teum-ink-tertiary); font-size: var(--teum-type-label); line-height: 24px; text-decoration: none; white-space: nowrap; }

.teum-breadcrumbs [aria-current="page"] { color: var(--teum-ink); font-weight: 500; overflow: hidden; text-overflow: ellipsis; }

.teum-breadcrumbs svg { width: 12px; height: 12px; }

.teum-breadcrumbs__separator { color: var(--teum-gray-400); }

.teum-breadcrumbs__ellipsis { display: grid !important; width: 22px; height: 22px; place-items: center; }

@media (hover: hover) and (pointer: fine) {
.teum-breadcrumbs a:hover { color: var(--teum-ink); }
}
}
